INSERT INTO cai_ranks(level,code,data) VALUES(1,'POSTULANTE','{"level": 1, "code": "POSTULANTE", "name": "Postulante", "motto": "«Primum audire»\nPrimero, escuchar", "threshold": 0, "bonus": 0, "requirement": "Ingreso aprobado: entrevista con un Comendador o superior, referencia de un miembro y 30 días de formación inicial.", "functions": "En formación y discernimiento. No sale a misión de campo. Estudio, oración, caridad y las primeras conversaciones dentro de su propia casa.", "shieldDescription": "Un escudo blanco liso con una pequeña cruz templaria roja. Simboliza la pureza de intención y el comienzo del camino: la cruz todavía no domina el campo.", "shieldUrl": "/ranks/POSTULANTE.png"}'::jsonb) ON CONFLICT(level) DO NOTHING;
INSERT INTO cai_ranks(level,code,data) VALUES(2,'COMPANERO_ARMAS','{"level": 2, "code": "COMPANERO_ARMAS", "name": "Compañero de Armas", "motto": "«Domus prima acies»\nLa casa es el primer frente", "threshold": 1, "bonus": 10, "requirement": "Misión Doméstica: PRX-01 y PRX-02 completadas y validadas.", "functions": "Infantería de la Orden. Su campo es su propia casa y su propio barrio. Puede salir a campo acompañado de un rango 4 o superior.", "shieldDescription": "Dos armas cruzadas, un hacha y una espada, detrás de un escudo con la cruz roja. Refleja su función de infantería inicial: la lucha directa contra el error en el núcleo familiar.", "shieldUrl": "/ranks/COMPANERO_ARMAS.png"}'::jsonb) ON CONFLICT(level) DO NOTHING;
INSERT INTO cai_ranks(level,code,data) VALUES(3,'ESCUDERO','{"level": 3, "code": "ESCUDERO", "name": "Escudero", "motto": "«Proximus meus, prima missio»\nMi prójimo, mi primera misión", "threshold": 101, "bonus": 20, "requirement": "Evangelización de Proximidad: PRX-03 y CAR-01 completadas y validadas.", "functions": "Apoyo doctrinal a la comunidad. Puede abrir fichas de secta en el mapa y salir a la calle acompañado. Primer rango con misiones de contenido.", "shieldDescription": "Un escudo con una lanza recta, flanqueada por una pequeña cruz roja y un báculo religioso. Simboliza el inicio del apoyo doctrinal a la comunidad.", "shieldUrl": "/ranks/ESCUDERO.png"}'::jsonb) ON CONFLICT(level) DO NOTHING;
INSERT INTO cai_ranks(level,code,data) VALUES(4,'SARGENTO_ARMAS','{"level": 4, "code": "SARGENTO_ARMAS", "name": "Sargento de Armas", "motto": "«Fundamenta teneo»\nSostengo los fundamentos", "threshold": 301, "bonus": 35, "requirement": "Vigilia de Fundamentos: examen integral de Catecismo y Biblia (FOR-03 y los cuatro módulos FOR-04).", "functions": "Mando de escuadra, de dos a tres miembros. Valida misiones de rangos 1 y 2. Primer rango autorizado a debatir, en formato informal.", "shieldDescription": "Un escudo circular dividido en blanco y negro, con una gran cruz roja central. Los dos campos son el estandarte Baucent de la Orden: negro para el mundo, blanco para los hermanos.", "shieldUrl": "/ranks/SARGENTO_ARMAS.png"}'::jsonb) ON CONFLICT(level) DO NOTHING;
INSERT INTO cai_ranks(level,code,data) VALUES(5,'CABALLERO_TEMPLE','{"level": 5, "code": "CABALLERO_TEMPLE", "name": "Caballero del Temple", "motto": "«Non nobis, Domine»\nNo a nosotros, Señor", "threshold": 651, "bonus": 60, "requirement": "Vigilia de Armas: HIT-CAB. Examen doctrinal integral, una misión de campo liderada y tres meses de constancia sin interrupción.", "functions": "Mando de pelotón, hasta ocho miembros. Organiza misiones propias y debates formales. Apadrina escuderos.", "shieldDescription": "Un caballero con armadura completa y manto blanco sobre su caballo de batalla, portando el estandarte Baucent. Primer rango con autoridad para organizar misiones propias y liderar pelotones.", "shieldUrl": "/ranks/CABALLERO_TEMPLE.png"}'::jsonb) ON CONFLICT(level) DO NOTHING;
INSERT INTO cai_ranks(level,code,data) VALUES(6,'COMENDADOR','{"level": 6, "code": "COMENDADOR", "name": "Comendador", "motto": "«Custos doctrinae»\nGuardián de la doctrina", "threshold": 1201, "bonus": 90, "requirement": "Encomienda: HIT-COM. Tres misiones de campo lideradas y una encomienda local activa y sostenida.", "functions": "Mando de encomienda local. Autoriza misiones de campo en su zona y valida evidencias hasta rango 4. Rol ejecutivo.", "shieldDescription": "Un gran castillo de tres torres fortificadas con una cruz roja sobre la torre central. Simboliza la defensa inexpugnable de la sana doctrina y el mando ejecutivo sobre las misiones activas.", "shieldUrl": "/ranks/COMENDADOR.png"}'::jsonb) ON CONFLICT(level) DO NOTHING;
INSERT INTO cai_ranks(level,code,data) VALUES(7,'PRECEPTOR','{"level": 7, "code": "PRECEPTOR", "name": "Preceptor", "motto": "«Doce ut credant»\nEnseña para que crean", "threshold": 2001, "bonus": 130, "requirement": "Cátedra: HIT-PRE. Diseñar y dictar un módulo formativo aprobado por el Capítulo.", "functions": "Cátedra de la Orden. Diseña la formación, certifica, supervisa el contenido y las redes. Rol académico, no ejecutivo.", "shieldDescription": "Un libro abierto con una cruz roja en el centro, flanqueado por un báculo de oro y la pluma de la Orden. El libro representa el Catecismo y la Biblia: madurez académica y responsabilidad de formar a los rangos menores.", "shieldUrl": "/ranks/PRECEPTOR.png"}'::jsonb) ON CONFLICT(level) DO NOTHING;
INSERT INTO cai_ranks(level,code,data) VALUES(8,'MARISCAL','{"level": 8, "code": "MARISCAL", "name": "Mariscal", "motto": "«Ubi mittor, eo»\nDonde me envían, voy", "threshold": 3201, "bonus": 180, "requirement": "Campaña Itinerante: HIT-MAR. Haber sido invitado y haber expuesto en tres congregaciones de otra confesión, en ciudades o barrios distintos.", "functions": "Mando itinerante. Dirige campañas fuera de la ciudad base y representa a la Orden ante otras comunidades.", "shieldDescription": "Dos espadas cruzadas bajo un yelmo de caballero blindado con penacho fluido. Representa la maestría en la estrategia: se gana demostrando capacidad de exponer la fe lejos de casa.", "shieldUrl": "/ranks/MARISCAL.png"}'::jsonb) ON CONFLICT(level) DO NOTHING;
INSERT INTO cai_ranks(level,code,data) VALUES(9,'SENESCAL','{"level": 9, "code": "SENESCAL", "name": "Senescal", "motto": "«Veritas in caritate»\nLa verdad en la caridad", "threshold": 5001, "bonus": 250, "requirement": "El Gran Debate: HIT-SEN. Organizar y sostener un debate público frente a cinco o más interlocutores simultáneos.", "functions": "Segundo del Gran Maestre. Preside el Capítulo en su ausencia y es última instancia en la validación de evidencias.", "shieldDescription": "Un escudo con la cruz roja, coronado por una mitra y flanqueado por una llave y un báculo. Distintivo de quien ha enfrentado y sostenido el gran debate.", "shieldUrl": "/ranks/SENESCAL.png"}'::jsonb) ON CONFLICT(level) DO NOTHING;
INSERT INTO cai_ranks(level,code,data) VALUES(10,'GRAN_MAESTRE','{"level": 10, "code": "GRAN_MAESTRE", "name": "Gran Maestre", "motto": "«Servus servorum veritatis»\nSiervo de los siervos de la verdad", "threshold": 7501, "bonus": 350, "requirement": "Elección por el Capítulo General: HIT-GM. Trayectoria completa, una obra de la Orden fundada y sostenida, y profesión del Voto de Fidelidad. No se alcanza solo por puntos.", "functions": "Cabeza de la Orden. Custodia la regla, el honor y la caridad de la Orden. Único rango electivo.", "shieldDescription": "Un águila bicéfala dorada, emblema de autoridad y de la doble naturaleza de la misión, militar y espiritual, sosteniendo una cruz pattée y un báculo, rodeada por el lema PAUPERES COMMILITONES CHRISTI TEMPLIQUE SALOMONIS (Pobres Compañeros de Cristo del Templo de Salomón).", "shieldUrl": "/ranks/GRAN_MAESTRE.png"}'::jsonb) ON CONFLICT(level) DO NOTHING;
INSERT INTO cai_milestones(code,level,points,data) VALUES('HIT-ING',1,0,'{"code": "HIT-ING", "name": "Aprobación de Ingreso", "level": 1, "requirement": "Entrevista con un Comendador o superior, referencia de un miembro activo y 30 días de formación inicial.", "evidence": "Acta de ingreso firmada", "points": 0}'::jsonb) ON CONFLICT(code) DO NOTHING;
INSERT INTO cai_milestones(code,level,points,data) VALUES('HIT-DOM',2,25,'{"code": "HIT-DOM", "name": "La Misión Doméstica", "level": 2, "requirement": "PRX-01 y PRX-02 completadas y validadas. Nadie defiende la fe fuera si no ha empezado por su propia casa.", "evidence": "Bitácoras validadas", "points": 25}'::jsonb) ON CONFLICT(code) DO NOTHING;
INSERT INTO cai_milestones(code,level,points,data) VALUES('HIT-PROX',3,40,'{"code": "HIT-PROX", "name": "Evangelización de Proximidad", "level": 3, "requirement": "PRX-03 y CAR-01 completadas y validadas: una conversación con el entorno y una secta local fichada.", "evidence": "Bitácora y ficha en el mapa", "points": 40}'::jsonb) ON CONFLICT(code) DO NOTHING;
INSERT INTO cai_milestones(code,level,points,data) VALUES('HIT-FUN',4,60,'{"code": "HIT-FUN", "name": "Vigilia de Fundamentos", "level": 4, "requirement": "FOR-03 y los cuatro módulos de FOR-04 aprobados. Examen integral de Catecismo y Biblia.", "evidence": "Exámenes aprobados en la plataforma", "points": 60}'::jsonb) ON CONFLICT(code) DO NOTHING;
INSERT INTO cai_milestones(code,level,points,data) VALUES('HIT-CAB',5,100,'{"code": "HIT-CAB", "name": "Vigilia de Armas", "level": 5, "requirement": "Examen doctrinal integral, una misión de campo liderada y tres meses consecutivos de actividad sin interrupción. Se profesa ante el Capítulo.", "evidence": "Acta de armadura firmada por un rango 7 o superior", "points": 100}'::jsonb) ON CONFLICT(code) DO NOTHING;
INSERT INTO cai_milestones(code,level,points,data) VALUES('HIT-COM',6,150,'{"code": "HIT-COM", "name": "La Encomienda", "level": 6, "requirement": "Tres misiones de campo lideradas (EST-02) y una encomienda local activa y sostenida.", "evidence": "Informes de misión y registro de la encomienda", "points": 150}'::jsonb) ON CONFLICT(code) DO NOTHING;
INSERT INTO cai_milestones(code,level,points,data) VALUES('HIT-PRE',7,200,'{"code": "HIT-PRE", "name": "La Cátedra", "level": 7, "requirement": "Diseñar y dictar un módulo formativo aprobado por el Capítulo (PRE-03 y PRE-01).", "evidence": "Material aprobado y grabación de la clase", "points": 200}'::jsonb) ON CONFLICT(code) DO NOTHING;
INSERT INTO cai_milestones(code,level,points,data) VALUES('HIT-MAR',8,300,'{"code": "HIT-MAR", "name": "La Campaña Itinerante", "level": 8, "requirement": "Haber sido invitado y haber expuesto en tres congregaciones de otra confesión, en ciudades o barrios distintos (DEB-04 x3).", "evidence": "Tres invitaciones escritas y tres grabaciones", "points": 300}'::jsonb) ON CONFLICT(code) DO NOTHING;
INSERT INTO cai_milestones(code,level,points,data) VALUES('HIT-SEN',9,400,'{"code": "HIT-SEN", "name": "El Gran Debate", "level": 9, "requirement": "Organizar y sostener un debate público frente a cinco o más interlocutores simultáneos (DEB-06).", "evidence": "Grabación completa y acta del Capítulo", "points": 400}'::jsonb) ON CONFLICT(code) DO NOTHING;
INSERT INTO cai_milestones(code,level,points,data) VALUES('HIT-GM',10,0,'{"code": "HIT-GM", "name": "Elección del Capítulo General", "level": 10, "requirement": "Trayectoria completa, una obra de la Orden fundada y sostenida, y profesión del Voto de Fidelidad. No es una misión: es una elección.", "evidence": "Acta de elección del Capítulo General", "points": 0}'::jsonb) ON CONFLICT(code) DO NOTHING;
